class Solution {
    public int solution(int[][] board) {
        int answer = 0;
        int height = board.length;
        int width = board[0].length;
        boolean[][] myBoard = new boolean[height][width];


        for (int i=0; i<height; i++) {
            for (int j=0; j<width; j++) {
                if (board[i][j] == 1) {
                    bfs(i, j, myBoard);
                }
            }
